function goTo(i){const c=document.querySelector('.rl .rcard[data-i="'+i+'"]');if(!c)return;if(c.classList.contains('acc')&&MOB())openAcc(c);act(i);c.scrollIntoView({behavior:RED()?'auto':'smooth',block:'start'});c.classList.remove('flash');void c.offsetWidth;c.classList.add('flash');setTimeout(()=>c.classList.remove('flash'),2000)}
